import numpy as np
from vispy import app, gloo
from vispy.util import keys
import time

vertex_shader = """
#version 120
attribute vec2 a_position;
attribute vec3 a_color;
attribute float a_size;
attribute float a_lifetime;
uniform float u_time;
varying vec3 v_color;
varying float v_alpha;
void main()
{
    float t = u_time - a_lifetime;
    float fade = 1.0 - clamp(t, 0.0, 1.0);
    v_color = a_color;
    v_alpha = fade;
    gl_Position = vec4(a_position, 0.0, 1.0);
    gl_PointSize = a_size * fade;
}
"""

fragment_shader = """
#version 120
varying vec3 v_color;
varying float v_alpha;
void main()
{
    float dist = length(gl_PointCoord - vec2(0.5, 0.5));
    float alpha = smoothstep(0.5, 0.2, dist) * v_alpha;
    gl_FragColor = vec4(v_color, alpha);
}
"""

class Canvas(app.Canvas):
    def __init__(self):
        app.Canvas.__init__(self, keys='interactive', size=(800, 600), title='Fireworks Simulation')
        self.program = gloo.Program(vertex_shader, fragment_shader)
        self.n_particles = 0
        self.max_particles = 2000
        self.particle_dtype = np.dtype([
            ('a_position', np.float32, 2),
            ('a_color',    np.float32, 3),
            ('a_size',     np.float32, 1),
            ('a_lifetime', np.float32, 1),
        ])
        self.particles = np.zeros(self.max_particles, dtype=self.particle_dtype)
        self.vbo = gloo.VertexBuffer(self.particles)
        self.program.bind(self.vbo)
        self.start_time = time.time()
        self.last_explosion = 0
        self.explosion_interval = 1.0
        self.set_explosion()
        self.timer = app.Timer('auto', connect=self.on_timer, start=True)
        gloo.set_state(clear_color='black', blend=True, blend_func=('src_alpha', 'one'))
        self.show()

    def set_explosion(self, pos=None):
        n = np.random.randint(80, 180)
        angle = np.linspace(0, 2 * np.pi, n, endpoint=False)
        speed = np.random.uniform(0.15, 0.45, n)
        colors = np.random.uniform(0.5, 1.0, (n, 3))
        if pos is None:
            x = np.random.uniform(-0.8, 0.8)
            y = np.random.uniform(-0.7, 0.7)
        else:
            x, y = pos
        t0 = time.time() - self.start_time
        for i in range(n):
            vx = np.cos(angle[i]) * speed[i]
            vy = np.sin(angle[i]) * speed[i]
            self.particles[i]['a_position'] = [x, y]
            self.particles[i]['a_color'] = colors[i]
            self.particles[i]['a_size'] = np.random.uniform(6, 14)
            self.particles[i]['a_lifetime'] = t0
        self.n_particles = n
        self.velocities = np.zeros((n, 2), dtype=np.float32)
        self.velocities[:, 0] = np.cos(angle) * speed
        self.velocities[:, 1] = np.sin(angle) * speed
        self.origins = np.tile([x, y], (n, 1))
        self.birth_time = t0

    def on_draw(self, event):
        gloo.clear()
        t = time.time() - self.start_time
        dt = t - self.birth_time
        if dt < 1.0:
            gravity = -0.6
            positions = self.origins + self.velocities * dt
            positions[:, 1] += 0.5 * gravity * dt * dt
            self.particles[:self.n_particles]['a_position'] = positions
            self.vbo.set_data(self.particles)
            self.program['u_time'] = t
            self.program.draw('points', vertices=self.n_particles)
        else:
            # Fade out
            self.program['u_time'] = t
            self.program.draw('points', vertices=self.n_particles)

    def on_resize(self, event):
        width, height = event.size
        gloo.set_viewport(0, 0, width, height)

    def on_timer(self, event):
        t = time.time() - self.start_time
        if t - self.last_explosion > self.explosion_interval:
            self.set_explosion()
            self.last_explosion = t
        self.update()

    def on_mouse_press(self, event):
        # Map mouse to [-1, 1] coordinates
        x = (event.pos[0] / self.size[0]) * 2 - 1
        y = 1 - (event.pos[1] / self.size[1]) * 2
        self.set_explosion((x, y))
        self.last_explosion = time.time() - self.start_time

    def on_key_press(self, event):
        if event.key == keys.ESCAPE:
            self.close()

if __name__ == '__main__':
    c = Canvas()
    app.run()
